def main():
    print("=" * 72)
    print("MSHQC STAGE 1 & STAGE 2 EXECUTION")
    print("=" * 72)

    print("\n[Stage 2.1] Menghapus file sumber (.cc), header (.h), dan berkas mati...")
    removed = 0
    for fpath in DEAD_FILES:
        if os.path.exists(fpath) or os.path.islink(fpath):
            os.remove(fpath)
            print(f"  - Deleted: {fpath}")
            removed += 1
    print(f"  Total berkas mati dihapus: {removed}")

    for dpath in EMPTY_DIRS:
        if os.path.isdir(dpath) and not os.listdir(dpath):
            os.rmdir(dpath)
            print(f"  - Removed empty dir: {dpath}/")

    print("\n[Stage 2.2] Memangkas GeometryOptimizer di optimizer.h & optimizer.cc (Menyisakan TrustRegionSOSCF)...")
    with open("include/mshqc/gradient/optimizer.h", "w", encoding="utf-8") as f:
        f.write(CLEAN_OPTIMIZER_H)
    print("  - Updated: include/mshqc/gradient/optimizer.h")

    with open("src/gradient/optimizer.cc", "w", encoding="utf-8") as f:
        f.write(CLEAN_OPTIMIZER_CC)
    print("  - Updated: src/gradient/optimizer.cc")

    print("\n[Stage 1.1] Menyuntikkan bindings.cc baru (Ergonomis + 100% HPC + Backward-Compatible)...")
    with open("python/bindings.cc", "w", encoding="utf-8") as f:
        f.write(NEW_BINDINGS_CC)
    print("  - Updated: python/bindings.cc")

    print("\n[Stage 1.2] Menyuntikkan Type Stubs _mshqc.pyi & __init__.py yang bersih...")
    with open("python/mshqc/_mshqc.pyi", "w", encoding="utf-8") as f:
        f.write(NEW_PYI)
    print("  - Updated: python/mshqc/_mshqc.pyi")

    with open("python/mshqc/__init__.py", "w", encoding="utf-8") as f:
        f.write(NEW_INIT_PY)
    print("  - Updated: python/mshqc/__init__.py")

    print("\n" + "=" * 72)
    print("SELESAI! Silakan kompilasi ulang C++ extension dengan perintah:")
    print("    pip install -v -e . --no-build-isolation")
    print("=" * 72)

if __name__ == "__main__":
    main()